/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// Intialize rebate transaction gets the source item sales tax group
/// </summary>
/// <param name = "_rebateTrans">TAMRebateTrans buffer</param>
/// <param name = "_rebateJournalTrans">TAMRebateJournalTrans buffer</param>
/// <param name = "_rebateDatePeriod">RebateDatePeriod given as part fo rebate transaction</param>
/// <returns>true or false</returns>
protected boolean inititalizeRebateTransaction(TAMRebateTrans _rebateTrans, TAMRebateJournalTrans _rebateJournalTrans, TAMRebateDatePeriod _rebateDatePeriod)
{
    boolean ret = next inititalizeRebateTransaction(_rebateTrans, _rebateJournalTrans, _rebateDatePeriod);

    boolean followTransItemGSTGroup = this.getTAMRebatePostingProfile().METFollowTransItemGSTGroup;

    if (ret && (followTransItemGSTGroup == NoYes::Yes || rebateParameters.METProcessByCustRebateInvByItemType == NoYes::Yes))
    {
        if (_rebateJournalTrans as TAMRebateJournalTransSalesOrder)
        {
            SalesLine salesLine;

            select firstonly ItemId, TaxItemGroup, InventDimId from salesLine
                where salesLine.DataAreaId == _rebateTrans.RefCompanyId
                && salesLine.TableId == _rebateTrans.RefTableId
                && salesLine.RecId == _rebateTrans.RefRecId;

            if (followTransItemGSTGroup == NoYes::Yes)
            {
                _rebateTrans.METTaxItemGroup = salesLine.TaxItemGroup;
            }

            if (rebateParameters.METProcessByCustRebateInvByItemType == NoYes::Yes)
            {
                METItemType itemType = METItemType::find(InventTable::metGetItemType(salesLine.ItemId, InventDim::find(salesLine.InventDimId).InventSiteId));

                _rebateTrans.METItemTypes = itemType.ItemType;
                _rebateTrans.METItemTypeDescription = itemType.Description;
            }
        }
        else 
        {
            if (rebateTable)
            {
                if (rebateTable.SourceType == TAMRebateSourceType::Ordered && rebateTable.ModuleInventCustVend == ModuleInventCustVend::Vend)
                {
                    PurchLine purchLine;

                    select firstonly ItemId, TaxItemGroup, InventDimId from purchLine
                        where purchLine.DataAreaId == _rebateTrans.RefCompanyId
                        && purchLine.TableId == _rebateTrans.RefTableId
                        && purchLine.RecId == _rebateTrans.RefRecId;

                    if (followTransItemGSTGroup == NoYes::Yes)
                    {
                        _rebateTrans.METTaxItemGroup = purchLine.TaxItemGroup;
                    }

                    if (rebateParameters.METProcessByCustRebateInvByItemType == NoYes::Yes)
                    {
                        METItemType itemType = METItemType::find(InventTable::metGetItemType(purchLine.ItemId, InventDim::find(purchLine.InventDimId).InventSiteId));

                        _rebateTrans.METItemTypes = itemType.ItemType;
                        _rebateTrans.METItemTypeDescription = itemType.Description;
                    }
                }
                else if (rebateTable.SourceType == TAMRebateSourceType::Invoice && rebateTable.ModuleInventCustVend == ModuleInventCustVend::Cust)
                {
                    CustInvoiceTrans custInvoiceTrans;

                    select firstonly ItemId, TaxItemGroup, InventDimId from custInvoiceTrans
                        where custInvoiceTrans.DataAreaId == _rebateTrans.RefCompanyId
                        && custInvoiceTrans.TableId == _rebateTrans.RefTableId
                        && custInvoiceTrans.RecId == _rebateTrans.RefRecId;

                    if (followTransItemGSTGroup == NoYes::Yes)
                    {
                        _rebateTrans.METTaxItemGroup = custInvoiceTrans.TaxItemGroup;
                    }

                    if (rebateParameters.METProcessByCustRebateInvByItemType == NoYes::Yes)
                    {
                        METItemType itemType = METItemType::find(InventTable::metGetItemType(custInvoiceTrans.ItemId, InventDim::find(custInvoiceTrans.InventDimId).InventSiteId));

                        _rebateTrans.METItemTypes = itemType.ItemType;
                        _rebateTrans.METItemTypeDescription = itemType.Description;
                    }
                }
            }
        }
    }

    return ret;
}

/// <summary>
/// Task182820-CB272_SalesInvoicing-rebates
/// Get Rebate posting profile
/// </summary>
/// <returns>TAMRebatePosting</returns>
public TAMRebatePosting getTAMRebatePostingProfile()
{
    return this.processByDeal ?
        TAMRebatePosting::find(rebateDeal.RebatePostingId, rebateDeal.ModuleInventCustVend) :
        TAMRebatePosting::find(rebateTable.RebatePostingId, rebateTable.ModuleInventCustVend);
}

