/// <summary>
/// CB_705
/// </summary>
/// <param name = "_journalTransaction"></param>
/// <param name = "_rebateQueryBuilder"></param>
/// <param name = "_rebateDate"></param>
/// <param name = "_rebateTable"></param>
/// <returns></returns>
protected boolean checkIfExtendedDimensionsAreMatched(
    Common _journalTransaction,
    TAMRebateQueryBuilder _rebateQueryBuilder,
    TAMRebateDate _rebateDate,
    TAMRebateTable _rebateTable)
{
    boolean ret = next checkIfExtendedDimensionsAreMatched(
        _journalTransaction,
        _rebateQueryBuilder,
        _rebateDate,
        _rebateTable);

    // if (met_isVendorRebate)
    if (rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend)
    {
        ret = METRebateMatchingHelper::checkIfPricingAttributesAreMatched(_journalTransaction, _rebateQueryBuilder, _rebateDate, _rebateTable)
           || METRebateMatchingHelper::checkIfRecordLinkedWithPriceTree(_journalTransaction, _rebateQueryBuilder, rebateTable);
    }

    return ret;
}

/// <summary>
/// CB_705
/// </summary>
/// <param name = "_rebateDateTrans"></param>
protected void updateOrInsertRebateDateTrans(TAMRebateDateTrans _rebateDateTrans)
{
    _rebateDateTrans.RebateDateRecId = rebateDateRecId;

    next updateOrInsertRebateDateTrans(_rebateDateTrans);
}

/// <summary>
/// CB_705
/// </summary>
/// <param name = "_rebateDatePeriod"></param>
/// <returns></returns>
protected boolean checkIfToCreateRebateDateTransactions(TAMRebateDatePeriod _rebateDatePeriod)
{
    boolean ret = next checkIfToCreateRebateDateTransactions(_rebateDatePeriod);

    if (TAMRebateParameters::find().NotOverwritePriceToZeroForSalesOrder &&
        rebateDeal.RebateOutputType == TAMRebateOutputType::Item &&
        rebateTransactionType == TAMRebateTransactionType::Provision)
    {
        this.metCreateRebateDateTransactionsForProvision(_rebateDatePeriod);
        ret = false;
    }

    return ret;
}

/// <summary>
/// CB_705
/// </summary>
/// <param name = "_rebateDate"></param>
/// <param name = "_rebateDatePeriod"></param>
protected void createRebateDateTransactions(TAMRebateDate _rebateDate, TAMRebateDatePeriod _rebateDatePeriod)
{
    if (rebateDeal.RebateOutputType == TAMRebateOutputType::Item &&
        rebateTransactionType == TAMRebateTransactionType::Rebate &&
        GUPParameters::find().EnablePriceTree &&
        !GUPRebateDateInstanceValue::METFindByRebateDateRecId(_rebateDate.RecId).RecId)
    {
        throw error(strFmt("@GlobalUnifiedPricing:RebateDateMissingAttribute", _rebateDate.RebateFromDate, _rebateDate.RebateToDate));
    }

    //rebateDateRecId = _rebateDate.RecId; //private, do we need it?

    next createRebateDateTransactions(_rebateDate, _rebateDatePeriod);
}

/// <summary>
/// CB_705
/// </summary>
/// <param name = "_rebateDatePeriod"></param>
private void metCreateRebateDateTransactionsForProvision(TAMRebateDatePeriod _rebateDatePeriod)
{
    TAMRebateDateTrans rebateDateTrans;
    FromDate fromDate = rebateJournalTrans.parmRebateFromDate();
    ToDate toDate = rebateJournalTrans.parmRebateToDate(); 

    select firstOnly RecId, RefRecId from rebateDateTrans
        order by ProcessDate desc
        where rebateDateTrans.RebateDeal == rebateDeal.RecId
           && (processByDeal || rebateDateTrans.RebateId == rebateTable.RebateId)
           && rebateDateTrans.RebateFromDate == fromDate
           && rebateDateTrans.RebateToDate == toDate
           && rebateDateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate
           && rebateDateTrans.RebatePosted;

    if (rebateDateTrans.RecId)
    {
        PurchTable purchTable = PurchTable::findRecId(rebateDateTrans.RefRecId);
        TAMRebateTransId rebateTransId = _rebateDatePeriod.getRebateTransId(fromDate, toDate, purchTable.PurchId);
        PurchLine purchLine;

        while select purchLine
            where purchLine.PurchId == purchTable.PurchId
        {
            TAMRebateTrans rebateTrans;
            rebateTrans.RebateId = rebateTable.RebateId;
            rebateTrans.Claimed = NoYes::Yes;
            rebateJournalTrans.setJournalTransaction(purchTable, purchLine);
            rebateJournalTrans.inititalizeRebateTransactionFromJournal(rebateTrans);
            rebateTrans.RebateTransId = rebateTransId;
            rebateTrans.RebateQty = this.convertRebateTransactionQuantity(rebateTrans);
            rebateTrans.RebateAmount = CurrencyExchangeHelper::curAmount2CurAmount(
                purchLine.PurchQty * purchLine.PurchPrice,
                purchLine.CurrencyCode,
                rebateDeal.RebateCurrencyCode,
                DateTimeUtil::date(purchLine.CreatedDateTime));
            rebateTrans.setPostingAmount(TAMRebateParameters::find().UseClaimProcess);
            rebateTrans.insert();
        }

        this.createRebateDateTrans(rebateTransId, 0);
    }
}

/// <summary>
/// CB705_VendorRebatePosting init the TAMRebateDateTrans vendor rebate type id
/// </summary>
/// <param name = "_rebateDateTrans"></param>
protected void initRebateDateTrans(TAMRebateDateTrans _rebateDateTrans)
{
    next initRebateDateTrans(_rebateDateTrans);

    if (rebateDeal.METInvoiceConsolidationByRebateType)
    {
        _rebateDateTrans.METVendRebateTypeId = rebateTable.METVendRebateTypeId;
    }
}

